<script setup>
import {ref,inject,onMounted} from 'vue'
import {adminRequest,formatDate} from '@/utils/adminApi'
const props=defineProps({healthOnly:Boolean}),navigation=inject('adminOpenNavigation')
const data=ref(null),error=ref(''),busy=ref(false)
const labels={favorites:'收藏同步',daily:'每日搜索',translations:'标签翻译'}
async function load(){busy.value=true;error.value='';try{data.value=await adminRequest('overview')}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="a-page" :aria-busy="busy"><header class="a-page-heading"><div class="a-page-title"><button class="a-button a-mobile-menu" @click="navigation">菜单</button><div><h1>{{healthOnly?'服务状态':'站点概览'}}</h1><p>查看数据新鲜度、运行状态与需要处理的事项。</p></div></div><button class="a-button" :disabled="busy" @click="load">刷新状态</button></header><div v-if="error" class="a-alert a-alert-error" role="alert">{{error}}</div><template v-if="data"><div v-if="!healthOnly" class="a-stat-grid"><article class="a-card a-stat"><span>收藏画廊</span><strong>{{data.counts.galleries}}</strong><small>{{data.counts.overrides}} 条人工覆盖</small></article><article class="a-card a-stat"><span>实体书单</span><strong>{{data.counts.books}}</strong><small>独立维护，不受来源同步覆盖</small></article><article class="a-card a-stat"><span>同步 worker</span><strong>{{data.workerAlive?'运行正常':'需要检查'}}</strong><small>{{data.counts.rules}} 个每日搜索分组</small></article></div><section class="a-card"><div class="a-section-heading"><h2>数据同步</h2><RouterLink class="a-button" to="/admin/tasks">任务与调度</RouterLink></div><div class="v2-schedules"><article v-for="schedule in data.schedules" :key="schedule.kind"><h3>{{labels[schedule.kind]}}</h3><p>最近成功：{{formatDate(data.successes[schedule.kind]?.at)}}</p><p>下次执行：{{schedule.enabled?formatDate(schedule.next_run_at):'自动同步已暂停'}}</p><small v-if="!data.successes[schedule.kind]">当前数据来自初次导入或其他任务，尚无此类任务成功记录。</small></article></div></section><section class="a-card"><div class="a-section-heading"><h2>业务服务</h2><RouterLink class="a-button" to="/admin/services">服务配置与验证</RouterLink></div><div v-if="data.checks.length" class="v2-status-list"><article v-for="check in data.checks" :key="check.name"><strong>{{check.name==='favorites'?'收藏来源':check.name==='ocr'?'文字识别':'翻译服务'}}</strong><span>{{!check.current?'配置已更改，需重新测试':check.ok?'上次验证通过':'上次验证未通过'}}</span><small>{{check.message}} · {{formatDate(check.checked_at)}}</small></article></div><p v-else>业务服务尚未验证。API 可访问不代表来源 Cookie 或付费服务凭证有效。</p><p v-for="usage in data.usage" :key="usage.name">Vision 本地请求计数：{{usage.count}} 次</p></section><section class="a-card"><div class="a-section-heading"><h2>备份</h2><RouterLink class="a-button" to="/admin/backups">管理备份</RouterLink></div><p>{{data.backup?'最近备份：'+formatDate(data.backup.modified*1000):'尚无数据库备份'}}</p></section></template></div></template>
